use super::*;
use semio_framework_value::{retirement::RetireOwned,ErasedSnapshotRetirement,serde};

#[derive(semio_framework_value::FactoryPayloadRetirement)]
struct Issuer<T:Send+Sync+'static>(std::marker::PhantomData<fn()->T>);
impl<T:RetireOwned+Sync> ArtifactOwnedValueRetirementFactory<T> for Issuer<T>{
 fn retirement_birth_bytes(&self,_:&T)->usize{semio_framework_value::owned_retirement_birth_bytes::<T>()}
 fn retire_owned(&self,value:T,g:RetainedCloneGrant)->Result<(Box<dyn ErasedSnapshotRetirement>,RetainedCloneProgress),(ValueError,T)>{semio_framework_value::admit_owned_retirement(value,g)}
}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64}}
struct OriginalTurnConstruction(RetainedCloneGrant);
impl semio_framework_value_native_owned::native_decoding::NativeDecodeConstructionRecipient for OriginalTurnConstruction{
 fn grant(&mut self,demand:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{if !retained_clone_grant_admits(self.0,demand){return Err(invalid("original JSON test turn does not admit construction demand"));}Ok(self.0)}
 fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{if g!=self.0||!p.fits(g){return Err(invalid("original JSON construction receipt changed its original turn"));}Ok(())}
}
fn actual<R>(run:impl FnOnce()->R)->(R,semio_framework_trace::HeapAllocationObservation){semio_framework_trace::observe_heap_allocations_on_this_thread(run)}
fn receipt(p:RetainedCloneProgress,heap:semio_framework_trace::HeapAllocationObservation,g:RetainedCloneGrant){assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}
fn source<T:RetireOwned+Sync>(value:T)->RetainedCloneSource<T>{let birth=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let g=RetainedCloneGrant{maximum_capacity_bytes:birth.capacity_bytes,maximum_depth:birth.depth,..grant()};let((source,p),heap)=actual(||RetainedCloneSource::admit_owned(value,(),g).map_err(|(error,..)|error).unwrap());receipt(p,heap,g);source}
fn close_source<T:RetireOwned+Sync>(source:&mut RetainedCloneSource<T>){for _ in 0..10000{if source.terminal_is_empty(){return;}let d=source.next_close_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.max(4096),maximum_capacity_bytes:d.capacity_bytes.max(4096),maximum_release_bytes:d.release_bytes.max(4096),maximum_depth:d.depth.max(64),..grant()};let(step,heap)=actual(||source.close_step(g).unwrap());receipt(step.progress(),heap,g);}panic!("original JSON source close stalled")}
fn schedule<M>(row:&serde_json::Value,cut:Option<usize>)->usize where M:NativeReceive<DslValue>+ArtifactCanonicalJsonTree+Sync+std::fmt::Debug+serde::Serialize{
 let bytes=row["wire"].as_str().unwrap().as_bytes().to_vec();let pointer=bytes.as_ptr();let mut root=source(bytes);let g=grant();let wire=root.try_borrow().unwrap().retain_projection(g).unwrap().0;assert_eq!(wire.borrow().unwrap().get().as_ptr(),pointer);
 let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<M>>=Arc::new(Issuer::<M>(std::marker::PhantomData));let callbacks=std::cell::Cell::new(0usize);let mut accept=|_|{callbacks.set(callbacks.get()+1);true};let mut original_retirement=semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new_retained(&mut accept);control.install_retirement_recipient(&mut original_retirement).unwrap();let(mut owner,p)=OriginalJsonReceiving::<M>::admit(wire,&factory,if row["header"]=="op"{b"op"}else{b""},|value|value,&control,g).map_err(|(error,..)|error).unwrap();assert!(p.fits(g));let mut turns=0;let mut output=None;let mut faulted=false;
 for _ in 0..100000{
  if cut==Some(turns){break;}
  let d=owner.demands(g.maximum_copy_bytes).unwrap();let mut foreign_accept=|_|true;let mut foreign=NativeDecodeControl::new_retained(&mut foreign_accept);let(result,heap)=actual(||owner.advance(&mut foreign,g.maximum_copy_bytes,g));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes,foreign.owned_bytes()),(0,0,0));for axis in 0..5{if axis==1&&d.copy_bytes==0||axis==2&&d.capacity_bytes==0||axis==3&&d.release_bytes==0{continue;}let denied=match axis{0=>RetainedCloneGrant{maximum_items:0,..g},1=>RetainedCloneGrant{maximum_copy_bytes:0,..g},2=>RetainedCloneGrant{maximum_capacity_bytes:0,..g},3=>RetainedCloneGrant{maximum_release_bytes:0,..g},_=>RetainedCloneGrant{maximum_depth:0,..g}};let admitted=control.owned_bytes();let calls=callbacks.get();let(step,heap)=actual(||owner.advance(&mut control,g.maximum_copy_bytes,denied).unwrap());receipt(step.progress(),heap,denied);assert_eq!(control.owned_bytes(),admitted);assert_eq!(callbacks.get(),calls);assert_eq!(step.progress(),Default::default());assert_eq!(owner.wire.as_ref().unwrap().borrow().unwrap().get().as_ptr(),pointer);}
  let admitted=control.owned_bytes();let mut construction=OriginalTurnConstruction(g);let(result,heap)=actual(||control.with_construction_recipient(&mut construction,|control|owner.advance(control,g.maximum_copy_bytes,g)));assert_eq!(control.owned_bytes()-admitted,heap.requested_bytes);let p=match result{Ok(step)=>step.progress(),Err(error)=>{faulted=true;error.retained_progress()}};receipt(p,heap,g);turns+=1;if faulted||owner.ready(){break;}
 }
 if cut.is_none(){assert_eq!(faulted,!row["canonical"].as_bool().unwrap());if !faulted{assert!(owner.ready(),"[DEBUG] original JSON receiving stalled case={} phase={:?} turns={} demand={:?}",row["name"],owner.phase,turns,owner.demands(g.maximum_copy_bytes));let(result,heap)=actual(||owner.take(g).unwrap());let(value,p)=result.unwrap();receipt(p,heap,g);assert_eq!(serde_json::to_value(value.borrow().unwrap().get()).unwrap(),row["value"]);output=Some(value);}}
 owner.begin_close();if let Some(output)=output.as_mut(){for _ in 0..10000{if output.terminal_is_empty(){break;}let d=output.close_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.max(4096),maximum_capacity_bytes:d.capacity_bytes.max(4096),maximum_release_bytes:d.release_bytes.max(4096),maximum_depth:d.depth.max(64),..g};let(step,heap)=actual(||output.close_step(g).unwrap());receipt(step.progress(),heap,g);}assert!(output.terminal_is_empty());}
 for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.max(4096),maximum_capacity_bytes:d.capacity_bytes.max(4096),maximum_release_bytes:d.release_bytes.max(4096),maximum_depth:d.depth.max(64),..g};let admitted=control.owned_bytes();let(step,heap)=actual(||control.with_retirement(g,|retirement|owner.close_step(retirement,g)).unwrap());assert_eq!(control.owned_bytes()-admitted,heap.requested_bytes);receipt(step.progress(),heap,g);}
 assert!(owner.terminal_is_empty());let((),heap)=actual(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close_source(&mut root);drop(control);assert!(original_retirement.terminal_is_empty());turns
}
#[test]
fn original_json_receiving_keeps_native_source_and_exact_physical_custody(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let turns=if row["value"].is_string(){schedule::<String>(row,None)}else if row["value"].is_array(){schedule::<Vec<String>>(row,None)}else{schedule::<u64>(row,None)};for cut in[0,1,2,turns/2,turns.saturating_sub(1)]{if row["value"].is_string(){schedule::<String>(row,Some(cut));}else if row["value"].is_array(){schedule::<Vec<String>>(row,Some(cut));}else{schedule::<u64>(row,Some(cut));}}}
 println!("[DEBUG] original JSON receiving native scalar corpus: exact serde output, original octet pointer, five denied currencies, five cuts and canonical refusal physically closed");
}
